import {clipDiagonalCaps} from './diagonal-caps.js';
import * as THREE from '../vendor/three.module.js';
const EPS=1e-6;
export function subtractRect(r,b){const x=Math.max(r[0],b[0]),y=Math.max(r[1],b[1]),xx=Math.min(r[2],b[2]),yy=Math.min(r[3],b[3]);if(xx<=x+EPS||yy<=y+EPS)return[r];return[[r[0],r[1],x,r[3]],[xx,r[1],r[2],r[3]],[x,r[1],xx,y],[x,yy,xx,r[3]]].filter(q=>q[2]-q[0]>EPS&&q[3]-q[1]>EPS);}
// Construct exposed box surfaces; overlapping walls, trims and ceilings have one
// surface owner. This removes duplicate faces rather than changing camera depth.
export const surfaceMetrics={calls:0,regenerated:0,reused:0};
function neighbors(entries,brute){if(brute){for(const a of entries)a.neighbors=entries.map((b,j)=>j).filter(j=>{const b=entries[j];return a!==b&&a.lo.every((lo,k)=>lo<=b.hi[k]+EPS&&a.hi[k]>=b.lo[k]-EPS);});return;}const buckets=new Map();for(const [i,a]of entries.entries()){a.neighborSet=new Set();const lo=a.lo.map(v=>Math.floor((v-EPS)/8)),hi=a.hi.map(v=>Math.floor((v+EPS)/8));for(let x=lo[0];x<=hi[0];x++)for(let y=lo[1];y<=hi[1];y++)for(let z=lo[2];z<=hi[2];z++){const key=x+','+y+','+z,cell=buckets.get(key)??[];for(const j of cell){const b=entries[j];if(a.lo.every((v,k)=>v<=b.hi[k]+EPS&&a.hi[k]>=b.lo[k]-EPS)){a.neighborSet.add(j);b.neighborSet.add(i);}}cell.push(i);buckets.set(key,cell);}}for(const a of entries){a.neighbors=[...a.neighborSet].sort((a,b)=>a-b);delete a.neighborSet;}}
export function exposeBoxSurfaces(root,excluded=new Set(),{force=false,bruteForce=false}={}){
 surfaceMetrics.calls++;
 root.updateMatrixWorld(true);const inverse=root.matrixWorld.clone().invert(),entries=[];
 root.traverse(m=>{if(m.userData.batchProxy||!m.isMesh||m.geometry.type!=='BoxGeometry'&&!m.userData.sourceBox)return;for(let q=m;q&&q!==root;q=q.parent)if(excluded.has(q)||q.userData.target)return;m.userData.sourceBox??=m.geometry.clone();const mat=inverse.clone().multiply(m.matrixWorld),e=mat.elements;if([0,1,2].some(r=>[0,1,2].filter(c=>Math.abs(e[c*4+r])>EPS).length!==1))return;const box=new THREE.Box3().setFromBufferAttribute(m.userData.sourceBox.attributes.position).applyMatrix4(mat);entries.push({m,box,mat,lo:box.min.toArray(),hi:box.max.toArray()});});
 neighbors(entries,bruteForce);let removed=0,regenerated=0,reused=0;
 entries.forEach(({m,box,mat},i)=>{const inverse=mat.clone().invert(),signature=entries[i].neighbors.map(j=>{const b=entries[j].box.clone().applyMatrix4(inverse);return [...b.min.toArray(),...b.max.toArray()].map(v=>Math.round(v/EPS)).join(',')+':'+(j<i);}).sort().join('|');if(!force&&m.userData.surfaceSignature===signature){reused++;if(m.userData.internalSurface)removed++;return;}m.userData.surfaceSignature=signature;regenerated++;const min=box.min.toArray(),max=box.max.toArray(),positions=[],normals=[],uvs=[],back=mat.clone().invert();for(let axis=0;axis<3;axis++)for(const sign of[-1,1]){const u=(axis+1)%3,v=(axis+2)%3,plane=sign<0?min[axis]:max[axis];let pieces=[[min[u],min[v],max[u],max[v]]];for(const j of entries[i].neighbors){if(!pieces.length)break;const b=entries[j].box,lo=entries[j].lo,hi=entries[j].hi;const inward=sign<0?hi[axis]>plane+EPS:lo[axis]<plane-EPS,outward=sign<0?lo[axis]<plane-EPS:hi[axis]>plane+EPS,coplanar=Math.abs((sign<0?lo[axis]:hi[axis])-plane)<EPS;if(inward&&(outward||(coplanar&&j<i)))pieces=pieces.flatMap(r=>subtractRect(r,[lo[u],lo[v],hi[u],hi[v]]));}
  for(const r of pieces){const corners=[[r[0],r[1]],[r[2],r[1]],[r[2],r[3]],[r[0],r[3]]],order=sign>0?[0,1,2,0,2,3]:[0,2,1,0,3,2];for(const k of order){const p=new THREE.Vector3(),n=new THREE.Vector3();p.setComponent(axis,plane);p.setComponent(u,corners[k][0]);p.setComponent(v,corners[k][1]);p.applyMatrix4(back);n.setComponent(axis,sign);n.transformDirection(back);uvs.push(p.x/8+.5,p.z/8+.5);positions.push(...p.toArray());normals.push(...n.toArray());}}}
  if(m.userData.internalSurface){m.visible=true;m.userData.internalSurface=false;}if(!positions.length){m.visible=false;m.userData.internalSurface=true;removed++;return;}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uvs,2));g.setAttribute('normal',new THREE.Float32BufferAttribute(normals,3));m.geometry.dispose();m.geometry=g;});clipDiagonalCaps(root,excluded,{force});surfaceMetrics.regenerated+=regenerated;surfaceMetrics.reused+=reused;return{boxes:entries.length,hidden:removed,regenerated,reused};
}
